# टोकरी pricing: promo codes

सबसे पहले मुख्य नतीजा: **उदाहरण कार्ट पर `fresh10` नहीं लगता (`below_minimum`)।** Infant formula हटाने के बाद eligible subtotal ₹863.50 बचता है, जबकि न्यूनतम सीमा ₹1,000.00 है। अगर formula को गिन लिया जाता, जैसी गलती मौजूदा module करता है, तो कार्ट ₹1,312.50 का दिखता और code गलत तरीके से लग जाता।

## 1. `pricing.ts`

```ts
// pricing.ts
export type Category = 'grocery' | 'household' | 'infant_formula';

export interface LineItem {
  sku: string;
  name: string;
  unitPrice: number; // रुपये में, GST सहित MRP, जैसे 189.00 (अधिकतम 2 दशमलव)
  qty: number;       // धनात्मक integer
  category: Category;
}

export interface Cart {
  items: LineItem[];
  memberTier: 'none' | 'plus';
}

/** हमेशा integer पैसे। */
export type Paise = number;

// ───────────── नीति-डेटा ─────────────

/** Finance की HSN mapping (spec §6)। */
export const GST_RATE_PCT: Readonly<Record<Category, number>> = {
  grocery: 0,
  household: 18,
  infant_formula: 18,
};

/** Legal: Infant Milk Substitutes Act, 1992. इन पर न promo, न membership छूट। */
export const NEVER_DISCOUNTED: ReadonlySet<Category> = new Set<Category>(['infant_formula']);

export const PLUS_MEMBER_DISCOUNT_BPS = 500; // 5%

export type PromoDiscount =
  | { readonly type: 'percent'; readonly bps: number }   // 1000 = 10%
  | { readonly type: 'fixed'; readonly paise: Paise };

export interface PromoDefinition {
  readonly code: string;                      // uppercase में
  readonly discount: PromoDiscount;
  readonly minEligibleSubtotalPaise: Paise;
  readonly validUntilIST: string;             // YYYY-MM-DD, सम्मिलित
  readonly categories?: readonly Category[];  // न दिया हो = सभी discountable categories
}

export const PROMO_CODES: readonly PromoDefinition[] = [
  { code: 'FRESH10', discount: { type: 'percent', bps: 1000 }, minEligibleSubtotalPaise: 100_000, validUntilIST: '2025-12-31' },
  { code: 'SAVE100', discount: { type: 'fixed', paise: 10_000 }, minEligibleSubtotalPaise: 75_000, validUntilIST: '2025-06-30' },
  { code: 'HOME15', discount: { type: 'percent', bps: 1500 }, minEligibleSubtotalPaise: 0, validUntilIST: '2025-12-31', categories: ['household'] },
];

// ───────────── परिणाम के types ─────────────

export type PromoRejectionReason = 'unknown' | 'expired' | 'below_minimum' | 'no_eligible_items';

export type PromoOutcome =
  | { status: 'none' }
  | { status: 'applied'; code: string; discountPaise: Paise }
  | {
      status: 'rejected';
      code: string;
      reason: PromoRejectionReason;
      eligibleSubtotalPaise?: Paise; // केवल below_minimum पर
      minimumPaise?: Paise;          // केवल below_minimum पर
    };

export interface PricedLine {
  sku: string;
  name: string;
  category: Category;
  qty: number;
  unitPricePaise: Paise;
  grossPaise: Paise;           // MRP × qty
  memberDiscountPaise: Paise;
  promoDiscountPaise: Paise;
  netPaise: Paise;             // ग्राहक यही चुकाता है (GST सहित)
  gstRatePct: number;
  gstPaise: Paise;             // netPaise में शामिल
  taxableValuePaise: Paise;    // netPaise − gstPaise
}

export interface PriceTotals {
  grossPaise: Paise;
  memberDiscountPaise: Paise;
  promoDiscountPaise: Paise;
  netPaise: Paise;             // कुल देय
  gstPaise: Paise;
  taxableValuePaise: Paise;
}

export interface PriceResult {
  lines: PricedLine[];
  totals: PriceTotals;
  promo: PromoOutcome;
}

// ───────────── शुद्ध गणित helpers ─────────────

const sum = (xs: readonly number[]): number => xs.reduce((s, x) => s + x, 0);

/** round_half_up(x × num ÷ den)। सभी integer ≥ 0 होने चाहिए। BigInt से overflow नहीं होता। */
export function mulDivRoundHalfUp(x: number, num: number, den: number): number {
  for (const v of [x, num, den]) {
    if (!Number.isSafeInteger(v) || v < 0) throw new RangeError(`integer ≥ 0 अपेक्षित, मिला: ${v}`);
  }
  if (den === 0) throw new RangeError('den शून्य नहीं हो सकता');
  const n = BigInt(x) * BigInt(num);
  const d = BigInt(den);
  return Number((2n * n + d) / (2n * d)); // floor(n/d + 1/2)
}

/**
 * amount को bases के अनुपात में बाँटता है। हर हिस्सा half-up round होता है।
 * बचा हुआ अंतर (+/−) सबसे बड़े base वाली line को जाता है (बराबरी हो तो कार्ट में पहली line)।
 * अगर इससे वह line 0 से नीचे या अपने base से ऊपर जाए, तो बाक़ी अंतर अगली सबसे बड़ी line को जाता है।
 */
export function allocateProRata(amount: Paise, bases: readonly Paise[]): Paise[] {
  const total = sum(bases);
  if (!Number.isSafeInteger(amount) || amount < 0 || amount > total) {
    throw new RangeError(`allocation राशि ${amount} सीमा [0, ${total}] से बाहर`);
  }
  if (total === 0) return bases.map(() => 0);

  const shares = bases.map((b) => mulDivRoundHalfUp(amount, b, total));
  let diff = amount - sum(shares);
  const order = bases.map((_, i) => i).sort((a, b) => bases[b] - bases[a] || a - b);

  for (const i of order) {
    if (diff === 0) break;
    const adjusted = Math.min(bases[i], Math.max(0, shares[i] + diff));
    diff -= adjusted - shares[i];
    shares[i] = adjusted;
  }
  return shares;
}

export function rupeesToPaise(rupees: number): Paise {
  const p = Math.round(rupees * 100);
  if (!Number.isFinite(rupees) || rupees < 0 || Math.abs(rupees * 100 - p) > 1e-6 || !Number.isSafeInteger(p)) {
    throw new RangeError(`अमान्य कीमत (₹, अधिकतम 2 दशमलव): ${rupees}`);
  }
  return p;
}

const IST_OFFSET_MS = 330 * 60 * 1000; // +05:30, IST में DST नहीं

/** किसी instant की IST कैलेंडर तारीख, YYYY-MM-DD रूप में। */
export function toISTDate(instant: Date): string {
  if (Number.isNaN(instant.getTime())) throw new RangeError('अमान्य Date');
  return new Date(instant.getTime() + IST_OFFSET_MS).toISOString().slice(0, 10);
}

function resolveTodayIST(today: string | Date | undefined): string {
  if (today === undefined) return toISTDate(new Date()); // केवल यहीं clock पढ़ा जाता है
  if (today instanceof Date) return toISTDate(today);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) throw new RangeError(`today YYYY-MM-DD (IST) होना चाहिए: ${today}`);
  return today;
}

export function normalizePromoCode(raw: string | undefined): string | undefined {
  if (raw === undefined) return undefined;
  const n = raw.trim().toUpperCase();
  return n === '' ? undefined : n;
}

function isPromoEligible(promo: PromoDefinition, category: Category): boolean {
  if (NEVER_DISCOUNTED.has(category)) return false;
  return promo.categories === undefined || promo.categories.includes(category);
}

// ───────────── pipeline ─────────────

interface WorkingLine {
  item: LineItem;
  unitPricePaise: Paise;
  gross: Paise;
  member: Paise;
  afterMember: Paise;
}

function buildWorkingLine(item: LineItem, memberTier: Cart['memberTier']): WorkingLine {
  if (!Object.hasOwn(GST_RATE_PCT, item.category)) throw new RangeError(`अज्ञात category: ${item.category}`);
  if (!Number.isSafeInteger(item.qty) || item.qty <= 0) throw new RangeError(`अमान्य qty (${item.sku}): ${item.qty}`);
  const unitPricePaise = rupeesToPaise(item.unitPrice);
  const gross = unitPricePaise * item.qty;
  if (!Number.isSafeInteger(gross)) throw new RangeError(`line राशि बहुत बड़ी: ${item.sku}`);

  const member =
    memberTier === 'plus' && !NEVER_DISCOUNTED.has(item.category)
      ? mulDivRoundHalfUp(gross, PLUS_MEMBER_DISCOUNT_BPS, 10_000)
      : 0;
  return { item, unitPricePaise, gross, member, afterMember: gross - member };
}

interface PromoEvaluation {
  outcome: PromoOutcome;
  discounts: Paise[];
}

function evaluatePromo(
  lines: readonly WorkingLine[],
  rawCode: string | undefined,
  todayIST: string,
  table: readonly PromoDefinition[],
): PromoEvaluation {
  const zeros = lines.map(() => 0);
  const code = normalizePromoCode(rawCode);
  if (code === undefined) return { outcome: { status: 'none' }, discounts: zeros };

  const reject = (
    reason: PromoRejectionReason,
    detail: { eligibleSubtotalPaise?: Paise; minimumPaise?: Paise } = {},
  ): PromoEvaluation => ({ outcome: { status: 'rejected', code, reason, ...detail }, discounts: zeros });

  const promo = table.find((p) => p.code === code);
  if (!promo) return reject('unknown');
  if (todayIST > promo.validUntilIST) return reject('expired'); // YYYY-MM-DD की string तुलना

  const eligible = lines
    .map((l, i) => ({ l, i }))
    .filter(({ l }) => l.gross > 0 && isPromoEligible(promo, l.item.category));
  if (eligible.length === 0) return reject('no_eligible_items');

  // न्यूनतम सीमा: eligible lines का MRP, member छूट से पहले
  const eligibleSubtotal = sum(eligible.map(({ l }) => l.gross));
  if (eligibleSubtotal < promo.minEligibleSubtotalPaise) {
    return reject('below_minimum', {
      eligibleSubtotalPaise: eligibleSubtotal,
      minimumPaise: promo.minEligibleSubtotalPaise,
    });
  }

  const discounts = [...zeros];
  const d = promo.discount;
  if (d.type === 'percent') {
    for (const { l, i } of eligible) discounts[i] = mulDivRoundHalfUp(l.afterMember, d.bps, 10_000);
  } else {
    const bases = eligible.map(({ l }) => l.afterMember);
    const amount = Math.min(d.paise, sum(bases)); // fixed छूट eligible राशि से अधिक नहीं
    const alloc = allocateProRata(amount, bases);
    eligible.forEach(({ i }, k) => {
      discounts[i] = alloc[k];
    });
  }
  return { outcome: { status: 'applied', code, discountPaise: sum(discounts) }, discounts };
}

function finalizeLine(w: WorkingLine, promoDiscount: Paise): PricedLine {
  const net = w.afterMember - promoDiscount;
  const rate = GST_RATE_PCT[w.item.category];
  const gst = mulDivRoundHalfUp(net, rate, 100 + rate); // GST सहित राशि से निकाला गया
  return {
    sku: w.item.sku,
    name: w.item.name,
    category: w.item.category,
    qty: w.item.qty,
    unitPricePaise: w.unitPricePaise,
    grossPaise: w.gross,
    memberDiscountPaise: w.member,
    promoDiscountPaise: promoDiscount,
    netPaise: net,
    gstRatePct: rate,
    gstPaise: gst,
    taxableValuePaise: net - gst,
  };
}

function sumTotals(lines: readonly PricedLine[]): PriceTotals {
  const s = (f: (l: PricedLine) => number) => sum(lines.map(f));
  return {
    grossPaise: s((l) => l.grossPaise),
    memberDiscountPaise: s((l) => l.memberDiscountPaise),
    promoDiscountPaise: s((l) => l.promoDiscountPaise),
    netPaise: s((l) => l.netPaise),
    gstPaise: s((l) => l.gstPaise),
    taxableValuePaise: s((l) => l.taxableValuePaise),
  };
}

/**
 * Entry point। `today` = IST की तारीख 'YYYY-MM-DD' या कोई Date instant।
 * `today` दिया जाए तो function पूरी तरह pure है।
 * `promoTable` मुख्यतः tests के लिए है।
 */
export function priceCart(
  cart: Cart,
  promoCode?: string,
  today?: string | Date,
  promoTable: readonly PromoDefinition[] = PROMO_CODES,
): PriceResult {
  const todayIST = resolveTodayIST(today);
  const working = cart.items.map((item) => buildWorkingLine(item, cart.memberTier));
  const { outcome, discounts } = evaluatePromo(working, promoCode, todayIST, promoTable);
  const lines = working.map((w, i) => finalizeLine(w, discounts[i]));
  return { lines, totals: sumTotals(lines), promo: outcome };
}
```

## 2. `pricing.test.ts`

```ts
import { describe, it, expect } from 'vitest';
import {
  priceCart, allocateProRata, mulDivRoundHalfUp, toISTDate,
  type Cart, type LineItem, type PromoDefinition, type PriceResult,
} from './pricing';

const li = (sku: string, unitPrice: number, qty: number, category: LineItem['category']): LineItem =>
  ({ sku, name: sku, unitPrice, qty, category });
const cart = (items: LineItem[], memberTier: Cart['memberTier'] = 'none'): Cart => ({ items, memberTier });

function expectInvariants(r: PriceResult) {
  for (const l of r.lines) {
    expect(l.netPaise).toBe(l.grossPaise - l.memberDiscountPaise - l.promoDiscountPaise);
    expect(l.gstPaise + l.taxableValuePaise).toBe(l.netPaise);
    expect(l.netPaise).toBeGreaterThanOrEqual(0);
    for (const v of Object.values(l)) if (typeof v === 'number') expect(Number.isInteger(v)).toBe(true);
    if (l.category === 'infant_formula') {
      expect(l.memberDiscountPaise).toBe(0);
      expect(l.promoDiscountPaise).toBe(0);
    }
  }
  const s = (k: keyof PriceResult['totals']) => r.lines.reduce((a, l) => a + (l as any)[k], 0);
  for (const k of Object.keys(r.totals) as (keyof PriceResult['totals'])[]) expect(r.totals[k]).toBe(s(k));
}

describe('mulDivRoundHalfUp', () => {
  it('ठीक .5 पर ऊपर, उससे कम पर नीचे', () => {
    expect(mulDivRoundHalfUp(4650, 500, 10_000)).toBe(233); // 232.5
    expect(mulDivRoundHalfUp(4649, 500, 10_000)).toBe(232); // 232.45
    expect(mulDivRoundHalfUp(21375, 18, 118)).toBe(3261);   // 3260.59
    expect(mulDivRoundHalfUp(44900, 18, 118)).toBe(6849);   // 6849.15
  });
  it('बड़े मानों पर float की तरह गलत नहीं होता', () => {
    expect(mulDivRoundHalfUp(Number.MAX_SAFE_INTEGER, 3, 3)).toBe(Number.MAX_SAFE_INTEGER);
  });
});

describe('allocateProRata', () => {
  it('बराबर lines: remainder पहली (सबसे बड़ी) line को', () => {
    expect(allocateProRata(10_000, [30_000, 30_000, 30_000])).toEqual([3334, 3333, 3333]);
  });
  it('remainder सबसे बड़ी line को जाता है, सबसे बड़े fractional हिस्से वाली को नहीं', () => {
    // 3999.6→4000, 3499.65→3500, 2499.75→2500 = 10000; −1 सबसे बड़ी line पर
    expect(allocateProRata(9_999, [40_000, 35_000, 25_000])).toEqual([3999, 3500, 2500]);
  });
  it('ऋणात्मक remainder line को 0 से नीचे नहीं ले जाता, अगली line पर spill होता है', () => {
    expect(allocateProRata(2, [100, 100, 100, 100])).toEqual([0, 0, 1, 1]);
  });
  it('पूरी राशि = कुल base', () => {
    expect(allocateProRata(777, [500, 277])).toEqual([500, 277]);
  });
  it('सीमा से बाहर की राशि पर throw', () => {
    expect(() => allocateProRata(101, [50, 50])).toThrow(RangeError);
  });
});

describe('GST (MRP में शामिल)', () => {
  it('grocery 0%, कुल = MRP, ऊपर से कुछ नहीं जुड़ता', () => {
    const r = priceCart(cart([li('apple', 189, 2, 'grocery')]), undefined, '2025-07-02');
    expect(r.totals).toMatchObject({ grossPaise: 37_800, netPaise: 37_800, gstPaise: 0 });
  });
  it('18% line पर GST = राशि × 18/118', () => {
    const r = priceCart(cart([li('formula', 449, 1, 'infant_formula')]), undefined, '2025-07-02');
    expect(r.lines[0]).toMatchObject({ netPaise: 44_900, gstPaise: 6_849, taxableValuePaise: 38_051 });
  });
});

describe('Plus membership', () => {
  it('5% per line half-up; formula पर कभी नहीं', () => {
    const r = priceCart(cart([li('banana', 46.5, 1, 'grocery'), li('formula', 449, 1, 'infant_formula')], 'plus'),
      undefined, '2025-07-02');
    expect(r.lines.map((l) => l.memberDiscountPaise)).toEqual([233, 0]);
    expectInvariants(r);
  });
  it('member पहले, promo बची राशि पर', () => {
    const r = priceCart(cart([li('rice', 1200, 1, 'grocery')], 'plus'), 'FRESH10', '2025-07-02');
    expect(r.lines[0]).toMatchObject({ memberDiscountPaise: 6_000, promoDiscountPaise: 11_400, netPaise: 102_600 });
  });
});

describe('FRESH10', () => {
  const c = (rupees: number) => cart([li('rice', rupees, 1, 'grocery'), li('formula', 449, 1, 'infant_formula')]);
  it('ठीक ₹1000 पर और अंतिम तारीख (सम्मिलित) पर लागू; formula अछूता', () => {
    const r = priceCart(c(1000), 'FRESH10', '2025-12-31');
    expect(r.promo).toEqual({ status: 'applied', code: 'FRESH10', discountPaise: 10_000 });
    expect(r.lines.map((l) => l.promoDiscountPaise)).toEqual([10_000, 0]);
    expect(r.totals).toMatchObject({ netPaise: 134_900, gstPaise: 6_849 });
    expectInvariants(r);
  });
  it('न्यूनतम में formula नहीं गिना जाता', () => {
    expect(priceCart(c(999.99), 'FRESH10', '2025-07-02').promo).toEqual({
      status: 'rejected', code: 'FRESH10', reason: 'below_minimum', eligibleSubtotalPaise: 99_999, minimumPaise: 100_000,
    });
  });
  it('अगले दिन expired', () => {
    expect(priceCart(c(1000), 'FRESH10', '2026-01-01').promo).toMatchObject({ reason: 'expired' });
  });
  it('केवल formula वाला कार्ट: no_eligible_items', () => {
    const r = priceCart(cart([li('formula', 449, 3, 'infant_formula')]), 'FRESH10', '2025-07-02');
    expect(r.promo).toMatchObject({ reason: 'no_eligible_items' });
  });
});

describe('SAVE100', () => {
  const three = cart([li('a', 300, 1, 'household'), li('b', 300, 1, 'household'), li('c', 300, 1, 'household')]);
  it('pro-rata allocation और per-line GST', () => {
    const r = priceCart(three, 'save100', '2025-06-15');
    expect(r.lines.map((l) => l.promoDiscountPaise)).toEqual([3334, 3333, 3333]);
    expect(r.lines.map((l) => l.gstPaise)).toEqual([4068, 4068, 4068]);
    expect(r.totals).toMatchObject({ promoDiscountPaise: 10_000, netPaise: 80_000, gstPaise: 12_204 }); // कुल पर निकालें तो 12203 आता
    expectInvariants(r);
  });
  it('allocation member छूट के बाद की राशि पर', () => {
    const r = priceCart(cart([li('a', 500, 1, 'household'), li('b', 300, 1, 'grocery')], 'plus'), 'SAVE100', '2025-06-30');
    expect(r.lines.map((l) => l.promoDiscountPaise)).toEqual([6_250, 3_750]);
  });
  it('IST मध्यरात्रि की सीमा', () => {
    expect(toISTDate(new Date('2025-06-30T18:29:59Z'))).toBe('2025-06-30');
    expect(toISTDate(new Date('2025-06-30T18:30:00Z'))).toBe('2025-07-01');
    expect(priceCart(three, 'SAVE100', new Date('2025-06-30T18:29:59Z')).promo.status).toBe('applied');
    expect(priceCart(three, 'SAVE100', new Date('2025-06-30T18:30:00Z')).promo).toMatchObject({ reason: 'expired' });
  });
  it('fixed छूट eligible राशि पर cap होती है (custom table)', () => {
    const table: PromoDefinition[] = [
      { code: 'BIG500', discount: { type: 'fixed', paise: 50_000 }, minEligibleSubtotalPaise: 0, validUntilIST: '2099-12-31' },
    ];
    const r = priceCart(cart([li('a', 120, 1, 'grocery'), li('b', 80, 1, 'household'), li('f', 449, 1, 'infant_formula')]),
      'big500', '2025-07-02', table);
    expect(r.promo).toEqual({ status: 'applied', code: 'BIG500', discountPaise: 20_000 });
    expect(r.lines.map((l) => l.netPaise)).toEqual([0, 0, 44_900]);
    expectInvariants(r);
  });
});

describe('HOME15', () => {
  it('केवल household; 15% half-up', () => {
    const r = priceCart(cart([li('soap', 12.3, 1, 'household'), li('dal', 100, 1, 'grocery')]), 'Home15', '2025-07-02');
    expect(r.lines[0]).toMatchObject({ promoDiscountPaise: 185, netPaise: 1_045, gstPaise: 159 }); // 184.5 → 185
    expect(r.lines[1].promoDiscountPaise).toBe(0);
  });
  it('household न हो तो no_eligible_items', () => {
    const r = priceCart(cart([li('dal', 100, 1, 'grocery'), li('f', 449, 1, 'infant_formula')]), 'HOME15', '2025-07-02');
    expect(r.promo).toMatchObject({ reason: 'no_eligible_items' });
  });
});

describe('code की हैंडलिंग', () => {
  const c = cart([li('rice', 1200, 1, 'grocery')]);
  it('case-insensitive, whitespace trim', () => {
    expect(priceCart(c, '  fReSh10 ', '2025-07-02').promo.status).toBe('applied');
  });
  it('अज्ञात या कई codes: checkout नहीं टूटता, कीमत बिना promo वाली', () => {
    const base = priceCart(c, undefined, '2025-07-02');
    for (const code of ['BOGUS', 'FRESH10,SAVE100']) {
      const r = priceCart(c, code, '2025-07-02');
